namespace sv_638b053f0169402a920361a0d3168157.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state and notifies subscribers on change.
/// In Blazor Server, "scoped" = per-circuit, so each user gets independent state.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// All interactive components subscribe to this to re-render.
    /// </summary>
    public event Action? OnChanged;

    /// <summary>
    /// Update both values in one batch, firing only a single notification.
    /// </summary>
    public void SetPreferences(Theme theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" title="Current theme">
    <span class="theme-icon">@GetIcon()</span>
    <span class="theme-label" style="color: @ThemeService.AccentColor;">
        @ThemeService.CurrentTheme
    </span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="theme-toggle px-3 py-2">
    <button class="btn btn-sm btn-outline-light w-100" @onclick="CycleTheme">
        @GetIcon() @ThemeService.CurrentTheme
    </button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
    }

    private string GetIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 500px; border-color: @ThemeService.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <div class="btn-group mb-3" role="group">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                <button type="button"
                        class="btn @(ThemeService.CurrentTheme == theme ? "btn-primary" : "btn-outline-secondary")"
                        style="@(ThemeService.CurrentTheme == theme ? $"background-color: {ThemeService.AccentColor}; border-color: {ThemeService.AccentColor};" : "")"
                        @onclick="() => ThemeService.CurrentTheme = theme">
                    @theme
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>
        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentColorChanged" />
            <span class="badge" style="background-color: @ThemeService.AccentColor; font-size: 1rem;">
                @ThemeService.AccentColor
            </span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeService.CurrentTheme</strong><br />
            Accent color: <span style="color: @ThemeService.AccentColor; font-weight: bold;">@ThemeService.AccentColor</span>
        </p>
        <div class="alert" style="background-color: @ThemeService.AccentColor; color: white;">
            This is how your accent color looks as a background.
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

